{
  "app": "my-awesome-app",
  "kill_timeout": 10,
  "kill_signal": "SIGTERM",
  "statics": [
    {
      "guest_path": "/app/public",
      "url_prefix": "/static"
    }
  ],
  "services": [
    {
      "protocol": "tcp",
      "internal_port": 8080,
      "concurrency": {
        "type": "connections",
        "hard_limit": 30,
        "soft_limit": 25
      },
      "ports": [
        {
          "port": 80,
          "handlers": ["http"],
          "force_https": true
        }
      ],
      "tcp_checks": [
        {
          "grace_period": "10s",
          "interval": "30s",
          "timeout": "5s",
          "restart_limit": 1
        }
      ],
      "http_checks": [
        {
          "grace_period": "5s",
          "interval": "20s",
          "timeout": "3s",
          "method": "GET",
          "path": "/health",
          "protocol": "http",
          "headers": {
            "User-Agent": "FlyHealthCheck/1.0"
          }
        }
      ]
    }
  ],
  "deploy": {
    "release_command": "bundle exec rake db:migrate",
    "strategy": "canary"
  },
  "mounts": {
    "source": "myapp_data",
    "destination": "/data",
    "processes": ["app"]
  },
  "env": {
    "LOG_LEVEL": "debug",
    "S3_BUCKET": "myapp-bucket"
  },
  "build": {
    "builder": "paketobuildpacks/builder:base",
    "buildpacks": [
      "paketo-buildpacks/nodejs",
      "paketo-buildpacks/npm"
    ],
    "args": [
      {
        "NODE_ENV": "production"
      }
    ],
    "build-target": "production",
    "image": "registry.fly.io/my-awesome-app:latest",
    "dockerfile": "./Dockerfile"
  },
  "experimental": {
    "auto_rollback": true,
    "private_network": true
  }
}

